from collections import deque


def can_split_two_teams(graph):
    n = len(graph)
    color = [0] * n
    for start in range(n):
        if color[start] != 0:
            continue
        color[start] = 1
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for nb in graph[node]:
                if color[nb] == 0:
                    color[nb] = -color[node]
                    queue.append(nb)
                elif color[nb] == color[node]:
                    return False
    return True
